"""Do the open TurboQuant decode PRs (vLLM #69273, #68834) help on AMD MI300X (gfx942)?

Both PRs gate their faster kernels on current_platform.is_cuda(); ROCm keeps the old path. This script runs the
vLLM decode op from main and from both PR heads WITHOUT installing vLLM (kernel sources are embedded, vLLM imports
are shimmed), once with the platform reported as ROCm (what MI300X gets today) and once forced through the CUDA-gated
paths (what enabling them on gfx942 would give). Outputs are checked against main; times are per decode call.
Sources: vllm-project/vllm main and refs/pull/69273, refs/pull/68834 (Apache-2.0), fetched 2026-11-25.
Run on an AMD AI Notebooks MI300X:  python -u tq_pr_rocm_bench.py
"""
BLOB = '{"main": "", "pr69273": "", "pr68834": "", "stage2": ""}'

import base64, importlib.util, json, math, os, sys, types, zlib, time
import torch, triton
import triton.language as tl

SRC = json.loads(BLOB)
src = {k: zlib.decompress(base64.b64decode(v)).decode() for k, v in SRC.items()}

class _Plat:
    force_cuda = False
    def is_cuda(self): return self.force_cuda
    def is_cuda_alike(self): return True
    def is_rocm(self): return True
    def is_xpu(self): return False
plat = _Plat()

def _mod(name):
    m = types.ModuleType(name); sys.modules[name] = m; return m
for n in ("vllm", "vllm.v1", "vllm.v1.attention", "vllm.v1.attention.ops"):
    _mod(n).__path__ = []
_mod("vllm.platforms").current_platform = plat
tu = _mod("vllm.triton_utils"); tu.tl = tl; tu.triton = triton
open("/tmp/tq_stage2.py", "w").write("import triton\nimport triton.language as tl\n" + src["stage2"])
_sp = importlib.util.spec_from_file_location("vllm.v1.attention.ops.triton_decode_attention", "/tmp/tq_stage2.py")
s2 = importlib.util.module_from_spec(_sp); sys.modules["vllm.v1.attention.ops.triton_decode_attention"] = s2
_sp.loader.exec_module(s2)

def load(key):
    path = f"/tmp/tq_{key}.py"; open(path, "w").write(src[key])
    spec = importlib.util.spec_from_file_location(f"tq_{key}", path)
    m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m); return m

MODS = {k: load(k) for k in ("main", "pr69273", "pr68834")}
dev = "cuda"
MSE, VQB = 4, 4

def hadamard(n):
    h = torch.ones(1, 1)
    while h.shape[0] < n:
        h = torch.cat([torch.cat([h, h], 1), torch.cat([h, -h], 1)], 0)
    return h / math.sqrt(n)

def make(B, L, Hk, D, seed=0):
    kps = math.ceil(D * MSE / 8) + 2; vps = math.ceil(D * VQB / 8) + 4; slot = kps + vps; slot += slot % 2
    bs = 16; nblk = math.ceil(L / bs)
    g = torch.Generator().manual_seed(seed)
    c = torch.randint(0, 256, (B * nblk, bs, Hk, slot), generator=g, dtype=torch.uint8)
    one = torch.tensor([1.0], dtype=torch.float16).view(torch.uint8); sm = torch.tensor([0.02], dtype=torch.float16).view(torch.uint8)
    c[..., kps - 2:kps] = one; c[..., kps + vps - 4:kps + vps - 2] = sm; c[..., kps + vps - 2:kps + vps] = sm
    bt = torch.arange(B * nblk, dtype=torch.int32).view(B, nblk)
    return c.to(dev), bt.to(dev), torch.full((B,), L, dtype=torch.int32, device=dev), kps

def call(m, q, c, bt, sl, Pi, cent, kps, splits):
    kw = dict(query=q, kv_cache=c, block_table=bt, seq_lens=sl, Pi=Pi, centroids=cent, scale=1 / math.sqrt(q.shape[-1]),
              mse_bits=MSE, key_packed_size=kps, value_quant_bits=VQB, key_fp8=False, norm_correction=True,
              PiT=Pi.T.contiguous(), max_num_kv_splits=splits)
    import inspect
    if "pi_is_hadamard" in inspect.signature(m.triton_turboquant_decode_attention).parameters:
        kw["pi_is_hadamard"] = True
    return m.triton_turboquant_decode_attention(**kw)

def timeit(fn, n=30):
    for _ in range(3): fn()
    torch.cuda.synchronize(); s, e = torch.cuda.Event(True), torch.cuda.Event(True); s.record()
    for _ in range(n): fn()
    e.record(); torch.cuda.synchronize(); return s.elapsed_time(e) / n * 1000

def main():
    print("torch", torch.__version__, "triton", triton.__version__, torch.cuda.get_device_name(0), flush=True)
    rows = []
    for (Hq, Hk, D) in ((28, 4, 128), (32, 8, 128)):
        Pi = hadamard(D).to(dev); cent = (torch.linspace(-2.5, 2.5, 2 ** MSE) / math.sqrt(D)).to(dev)
        for (B, L) in ((1, 4096), (1, 32768), (8, 16384), (16, 8192), (32, 8192)):
            c, bt, sl, kps = make(B, L, Hk, D)
            q = torch.randn(B, Hq, D, device=dev, dtype=torch.bfloat16)
            plat.force_cuda = False
            ref = call(MODS["main"], q, c, bt, sl, Pi, cent, kps, 32).float()
            base = timeit(lambda: call(MODS["main"], q, c, bt, sl, Pi, cent, kps, 32))
            line = {"Hq": Hq, "Hk": Hk, "B": B, "L": L, "main_rocm_us": round(base, 1)}
            for key in ("pr69273", "pr68834"):
                for forced in (False, True):
                    plat.force_cuda = forced; best = None
                    for sp in (16, 32, 64, 128):
                        try:
                            out = call(MODS[key], q, c, bt, sl, Pi, cent, kps, sp).float()
                            err = ((out - ref).norm() / ref.norm()).item()
                            us = timeit(lambda: call(MODS[key], q, c, bt, sl, Pi, cent, kps, sp))
                        except Exception as ex:
                            line[f"{key}_{'cudapath' if forced else 'rocm'}_err"] = repr(ex)[:200]; continue
                        if err < 2e-2 and (best is None or us < best[0]):
                            best = (us, sp, err)
                    if best:
                        tag = f"{key}_{'cudapath' if forced else 'rocm'}"
                        line[tag + "_us"] = round(best[0], 1); line[tag + "_splits"] = best[1]
                        line[tag + "_x"] = round(base / best[0], 2); line[tag + "_relerr"] = float(f"{best[2]:.1e}")
            plat.force_cuda = False
            rows.append(line); print("RESULT", json.dumps(line), flush=True)
    json.dump(rows, open("tq_pr_rocm_bench.json", "w"), indent=1)
    print("DONE", flush=True)

if __name__ == "__main__":
    main()
